package httpapi
import("bytes";"context";"net/http/httptest";"strconv";"testing";"task191-reproof/internal/service";"task191-reproof/internal/store")
func TestBug10_InvalidDirectionIsBadRequest(t *testing.T){st,err:=store.Open(t.TempDir()+"/http.db");if err!=nil{t.Fatal(err)};defer st.Close();app:=service.New(st);srv:=New(app);tg,err:=app.CreateTarget(context.Background(),"http-direction","");if err!=nil{t.Fatal(err)};a,err:=app.CreateAction(context.Background(),tg.ID,"compile","");if err!=nil{t.Fatal(err)};r:=httptest.NewRequest("POST","/api/actions/"+strconv.FormatInt(a.ID,10)+"/logs",bytes.NewBufferString(`{"logs":[{"action_id":1,"seq":1,"path":"x","direction":"bad","hash":"h"}]}`));r.Header.Set("Content-Type","application/json");w:=httptest.NewRecorder();srv.Handler().ServeHTTP(w,r);if w.Code!=400{t.Fatalf("expected 400, got %d body=%s",w.Code,w.Body.String())}}
